        public ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.ITXT:
                {
                    if (lastParsed.ShortCircuit((int)TerminalMenuItem_FieldIndex.ItemText, translationParams)) return ParseResult.Stop;
                    _ItemTextLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.ItemText;
                }
                case RecordTypeInts.RNAM:
                {
                    if (lastParsed.ShortCircuit((int)TerminalMenuItem_FieldIndex.ResultText, translationParams)) return ParseResult.Stop;
                    _ResultTextLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.ResultText;
                }
                case RecordTypeInts.ANAM:
                {
                    if (lastParsed.ShortCircuit((int)TerminalMenuItem_FieldIndex.MenuItemFlags, translationParams)) return ParseResult.Stop;
                    _MenuItemFlagsLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.MenuItemFlags;
                }
                case RecordTypeInts.INAM:
                {
                    _DisplayNoteLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.DisplayNote;
                }
                case RecordTypeInts.TNAM:
                {
                    _SubMenuLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.SubMenu;
                }
                case RecordTypeInts.SCHR:
                {
                    if (!lastParsed.ParsedIndex.HasValue
                        || lastParsed.ParsedIndex.Value <= (int)TerminalMenuItem_FieldIndex.SubMenu)
                    {
                        this._EmbeddedScript = ScriptFieldsBinaryOverlay.ScriptFieldsFactory(
                            stream: stream,
                            package: _package,
                            translationParams: translationParams.DoNotShortCircuit());
                        return new ParseResult((int)TerminalMenuItem_FieldIndex.EmbeddedScript, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)TerminalMenuItem_FieldIndex.SCDA)
                    {
                        _SCHRLocation = (stream.Position - offset);
                        return new ParseResult((int)TerminalMenuItem_FieldIndex.SCHR, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                this._EmbeddedScript = ScriptFieldsBinaryOverlay.ScriptFieldsFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: translationParams.DoNotShortCircuit());
                                return new ParseResult((int)TerminalMenuItem_FieldIndex.EmbeddedScript, type);
                            }
                            case 1:
                            {
                                _SCHRLocation = (stream.Position - offset);
                                return new ParseResult((int)TerminalMenuItem_FieldIndex.SCHR, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.CTDA:
                {
                    this.Conditions = BinaryOverlayList.FactoryByArray<IConditionGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: Condition_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)TerminalMenuItem_FieldIndex.Conditions;
                }
                case RecordTypeInts.SCDA:
                {
                    _SCDALocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.SCDA;
                }
                case RecordTypeInts.SCRO:
                {
                    _SCROLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.SCRO;
                }
                case RecordTypeInts.SCRV:
                {
                    _SCRVLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.SCRV;
                }
                case RecordTypeInts.SCTX:
                {
                    _SCTXLocation = (stream.Position - offset);
                    return (int)TerminalMenuItem_FieldIndex.SCTX;
                }
                case RecordTypeInts.SCVR:
                {
